#include "stdlib/blas/base/ctrsm.h"
#include "stdlib/complex/float32/ctor.h"
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <time.h>
#include <sys/time.h>

#define NAME "ctrsm"
#define ITERATIONS 1000000
#define REPEATS 3
#define MIN 1
#define MAX 3

/**
* Prints the TAP version.
*/
static void print_version( void ) {
	printf( "TAP version 13\n" );
}

/**
* Prints the TAP summary.
*
* @param total     total number of tests
* @param passing   total number of passing tests
*/
static void print_summary( int total, int passing ) {
	printf( "#\n" );
	printf( "1..%d\n", total );
	printf( "# total %d\n", total );
	printf( "# pass  %d\n", passing );
	printf( "#\n" );
	printf( "# ok\n" );
}

/**
* Prints benchmark results.
*
* @param iterations   number of iterations
* @param elapsed      elapsed time in seconds
*/
static void print_results( int iterations, double elapsed ) {
	double rate = (double)iterations / elapsed;
	printf( "  ---\n" );
	printf( "  iterations: %d\n", iterations );
	printf( "  elapsed: %0.9f\n", elapsed );
	printf( "  rate: %0.9f\n", rate );
	printf( "  ...\n" );
}

/**
* Returns a clock time.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Generates a random float on the interval [0,1).
*
* @return random number
*/
static float rand_float( void ) {
	int r = rand();
	return (float)r / ( (float)RAND_MAX + 1.0f );
}

/**
* Runs a benchmark (base interface).
*
* @param iterations   number of iterations
* @param N            matrix dimension
* @return             elapsed time in seconds
*/
static double benchmark1( int iterations, int N ) {
	stdlib_complex64_t alpha;
	float *A;
	float *B;
	double elapsed;
	double t;
	int i;

	alpha = stdlib_complex64( 1.0f, 0.0f );
	A = (float *) malloc( N * N * 2 * sizeof( float ) );
	B = (float *) malloc( N * N * 2 * sizeof( float ) );
	for ( i = 0; i < N*N*2; i++ ) {
		A[ i ] = ( rand_float()*2.0f ) - 1.0f;
		B[ i ] = ( rand_float()*2.0f ) - 1.0f;
	}
	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		c_ctrsm( CblasRowMajor, CblasLeft, CblasUpper, CblasNoTrans, CblasNonUnit, N, N, alpha, (const void *)A, N, (void *)B, N );
		if ( B[ 0 ] != B[ 0 ] ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = tic() - t;
	if ( B[ 0 ] != B[ 0 ] ) {
		printf( "should not return NaN\n" );
	}
	free( A );
	free( B );
	return elapsed;
}

/**
* Runs a benchmark (ndarray interface).
*
* @param iterations   number of iterations
* @param N            matrix dimension
* @return             elapsed time in seconds
*/
static double benchmark2( int iterations, int N ) {
	float *A;
	float *B;
	double elapsed;
	double t;
	int i;

	A = (float *) malloc( N * N * 2 * sizeof( float ) );
	B = (float *) malloc( N * N * 2 * sizeof( float ) );
	for ( i = 0; i < N*N*2; i++ ) {
		A[ i ] = ( rand_float()*2.0f ) - 1.0f;
		B[ i ] = ( rand_float()*2.0f ) - 1.0f;
	}
	t = tic();
	for ( i = 0; i < iterations; i++ ) {
		c_ctrsm_ndarray( CblasRowMajor, CblasLeft, CblasUpper, CblasNoTrans, CblasNonUnit, N, N, 1.0f, 0.0f, (const void *)A, N, 0, (void *)B, N, 0 );
		if ( B[ 0 ] != B[ 0 ] ) {
			printf( "should not return NaN\n" );
			break;
		}
	}
	elapsed = tic() - t;
	if ( B[ 0 ] != B[ 0 ] ) {
		printf( "should not return NaN\n" );
	}
	free( A );
	free( B );
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	double elapsed;
	int count;
	int iter;
	int len;
	int i;
	int j;

	srand( time( NULL ) );

	print_version();
	count = 0;
	for ( i = MIN; i <= MAX; i++ ) {
		len = (int)pow( 10, i );
		iter = ITERATIONS / (int)pow( 10, i-1 );
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:N=%d\n", NAME, len );
			elapsed = benchmark1( iter, len );
			print_results( iter, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
		for ( j = 0; j < REPEATS; j++ ) {
			count += 1;
			printf( "# c::%s:ndarray:N=%d\n", NAME, len );
			elapsed = benchmark2( iter, len );
			print_results( iter, elapsed );
			printf( "ok %d benchmark finished\n", count );
		}
	}
	print_summary( count, count );
}
